import{_ as e,o as a,c as s,a2 as r}from"./chunks/framework.BZO4qERu.js";const d=JSON.parse('{"title":"Supermarket","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/supermarket.md","filePath":"zh/guides/supermarket.md","lastUpdated":1788855895000}'),l={name:"zh/guides/supermarket.md"};function i(o,t,n,p,h,k){return a(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="supermarket" tabindex="-1">Supermarket <a class="header-anchor" href="#supermarket" aria-label="Permalink to &quot;Supermarket&quot;">​</a></h1><p>Supermarket 是 Memoh 内置的<strong>连接器</strong>和 <strong>Skills</strong> 目录。连接器把第三方服务（GitHub、Notion 这类）绑到 Bot 上；Skills 是 Agent 可按需加载的可复用流程。</p><p>Web UI 会在 Settings 下显示 Supermarket，提供两个 tab：</p><ul><li><strong>Connectors</strong></li><li><strong>Skills</strong></li></ul><p>服务器<a href="/zh/guides/connectors.html#前提">配置了 Connect-It</a> 时，<strong>Connectors</strong> 排在第一个，也是默认落地的 tab；没配置时这个 tab 不显示，默认落在 <strong>Skills</strong>。</p><hr><h2 id="连接一个服务" tabindex="-1">连接一个服务 <a class="header-anchor" href="#连接一个服务" aria-label="Permalink to &quot;连接一个服务&quot;">​</a></h2><p><strong>Connectors</strong> tab 列出可以通过 OAuth 或 API Key 连给 Bot 的服务。挑一个点 <strong>Connect</strong>，选目标 Bot，完成授权即可。完整流程——认证方式、连接状态、工具怎么到 Bot 手上——见<a href="/zh/guides/connectors.html">连接器</a>。</p><hr><h2 id="安装-skill" tabindex="-1">安装 Skill <a class="header-anchor" href="#安装-skill" aria-label="Permalink to &quot;安装 Skill&quot;">​</a></h2><ol><li>在 Web UI 中打开 <strong>Supermarket</strong>。</li><li>切到 <strong>Skills</strong> tab。</li><li>选择一个 Skill 并点击 <strong>Install</strong>，或进入 Skill 详情页点击 <strong>Install to Bot</strong>。</li><li>选择目标 Bot。</li><li>确认安装。</li><li>Skill 会出现在该 Bot 的 <strong>Skills</strong> tab 中。</li></ol><p>Skill 会安装到 Bot 工作区内的 managed skills 目录（<code>/data/skills/&lt;skill-name&gt;</code>）。Skill 详情页展示作者、版本、来源 registry 和链接。加载与使用方式见 <a href="/zh/guides/skills.html">Skills</a>。</p><hr><h2 id="配置-supermarket" tabindex="-1">配置 Supermarket <a class="header-anchor" href="#配置-supermarket" aria-label="Permalink to &quot;配置 Supermarket&quot;">​</a></h2><p>默认情况下，Memoh 会从这里读取 Supermarket 内容：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">supermarket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://supermarket.memoh.ai&quot;</span></span></code></pre></div><p>运维方可以把 <code>supermarket.base_url</code> 指向其它可信目录。该 endpoint 会用于连接器列表、Skill 列表、Skill 详情和 Skill 下载。Skills tab 中的 <strong>Registry</strong> 筛选可以只看某一个上游 registry 的结果。</p><hr><h2 id="贡献" tabindex="-1">贡献 <a class="header-anchor" href="#贡献" aria-label="Permalink to &quot;贡献&quot;">​</a></h2><p>新的 Skills 可提交到：</p><ul><li><a href="https://github.com/felinics/supermarket" target="_blank" rel="noreferrer">felinics/supermarket</a></li></ul>`,21)])])}const g=e(l,[["render",i]]);export{d as __pageData,g as default};
